def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    total_alive = 1 + len(alive_opponents)
    units = int(supply // WATER_REQ)
    scarce = units < total_alive
    very_scarce = units <= max(0, total_alive - 2)

    highest_prev_bid = 0
    desperate_opp = False
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            if prev['bid'] > highest_prev_bid:
                highest_prev_bid = prev['bid']
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 2:
            desperate_opp = True

    if hp <= 1:
        base = DAILY_SALARY * 0.98
    elif no_water_days >= 2:
        base = DAILY_SALARY * 0.95
    elif hp <= 3:
        base = DAILY_SALARY * 0.82
    elif very_scarce:
        base = DAILY_SALARY * 0.72
    elif scarce:
        base = DAILY_SALARY * 0.58
    else:
        base = DAILY_SALARY * 0.34

    if highest_prev_bid > 0:
        if hp <= 3 or no_water_days >= 1 or scarce:
            target = highest_prev_bid + 1.5
            if target > base:
                base = target
        elif highest_prev_bid >= DAILY_SALARY * 0.9:
            base = min(base, DAILY_SALARY * 0.3)

    if desperate_opp and (hp > 3 and no_water_days == 0) and scarce:
        base = min(base, DAILY_SALARY * 0.45)

    if not alive_opponents:
        base = DAILY_SALARY * 0.25

    if base > budget:
        return budget
    if base < 0:
        return 0
    return base

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append(o)

    # If no opponents, bid conservatively but ensure we can meet requirement.
    if not alive_opponents:
        target = min(my_status['budget'], DAILY_SALARY * 0.35)
        return max(0.0, float(target))

    # Read yesterday bids from immediate previous_trace only.
    prev_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate how aggressive opponents are.
    if prev_bids:
        highest_prev = max(prev_bids)
        lowest_prev = min(prev_bids)
        # median without heavy history; compute from current list only.
        sorted_b = sorted(prev_bids)
        n = len(sorted_b)
        if n % 2 == 1:
            median_prev = sorted_b[int(n // 2)]
        else:
            median_prev = 0.5 * (sorted_b[int(n // 2) - 1] + sorted_b[int(n // 2)])
    else:
        highest_prev = 0.0
        lowest_prev = 0.0
        median_prev = DAILY_SALARY * 0.5

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Supply pressure: closer to MIN_SUPPLY means tighter water, so bid more.
    # Map supply in [15,25] -> pressure in [1.2,0.8]
    if MAX_SUPPLY > MIN_SUPPLY:
        t = (supply - float(MIN_SUPPLY)) / (float(MAX_SUPPLY - MIN_SUPPLY))
    else:
        t = 0.5
    pressure_mult = 1.2 - 0.4 * float(t)

    # If we are in danger, overbid to avoid another no-water day.
    danger = (hp <= 2.0) or (no_water_days >= 2)

    # If opponents were extremely aggressive yesterday, expect continuation.
    if highest_prev >= DAILY_SALARY * 0.85:
        if danger:
            bid = DAILY_SALARY * 0.95 * pressure_mult
        else:
            # Shade but still contest.
            bid = max(DAILY_SALARY * 0.45, highest_prev + 1.0) * 0.85 * pressure_mult
    else:
        # Otherwise, bid slightly above median to win share without wasting.
        # If their lowest was very low, we can bid closer to that.
        base = median_prev
        if lowest_prev > 0.0:
            base = 0.6 * median_prev + 0.4 * lowest_prev
        bid = (base + 1.5) * 0.9 * pressure_mult
        if danger:
            bid *= 1.25

    # Ensure bid is within budget and non-negative.
    bid = float(bid)
    if bid < 0.0:
        bid = 0.0
    bid = min(bid, budget)

    # If budget is too low, bid whatever we can.
    if budget <= DAILY_SALARY * 0.2:
        return max(0.0, budget)

    # Keep bid from going excessively high; still contest.
    cap = min(budget, DAILY_SALARY * (0.95 if danger else 0.75) * pressure_mult)
    bid = min(bid, cap)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_opponents = len(alive_opponents)

    # Calculate fair share based on supply
    fair_share_bid = (DAILY_SALARY * 0.5) if (supply / (num_opponents + 1)) >= WATER_REQ else (DAILY_SALARY * 0.75)

    # Emergency survival
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    return min(my_status['budget'], fair_share_bid)
